public class DriverMouse implements Mouse {

    private final Driver driver;

    public DriverMouse(Driver driver) {
        this.driver = driver;
    }

    private Integer duration;
    private final List<Map<String, Object>> actions = new ArrayList();
    private Number x, y;

    private Map<String, Object> moveAction(int x, int y) {
        // {"type":"pointer","id":"1","actions":[{"type":"pointerMove","x":250,"y":250}]}        
        Map<String, Object> map = new HashMap();
        map.put("type", "pointerMove");
        map.put("x", x);
        map.put("y", y);
        if (duration != null) {
            map.put("duration", duration);
        }
        return map;
    }

    @Override
    public DriverMouse duration(Integer duration) {
        this.duration = duration;
        return this;
    }

    @Override
    public DriverMouse pause(Integer duration) {
        Map<String, Object> map = new HashMap();
        map.put("type", "pause");
        map.put("duration", duration);
        actions.add(map);
        return this;
    }

    @Override
    public DriverMouse move(String locator) {
        Map<String, Object> map = driver.position(locator);
        Number x = (Number) map.get("x");
        Number y = (Number) map.get("y");
        Number width = (Number) map.get("width");
        Number height = (Number) map.get("height");
        return move(x.intValue() + width.intValue() / 2, y.intValue() + height.intValue() / 2);
    }

    @Override
    public DriverMouse move(Number x, Number y) {
        this.x = x == null ? 0 : x;
        this.y = y == null ? 0 : y;
        Map<String, Object> action = moveAction(this.x.intValue(), this.y.intValue());
        actions.add(action);
        return this;
    }

    @Override
    public DriverMouse offset(Number x, Number y) {
       if (x == null) {
           x = 0;
       }
       if (y == null) {
           y = 0;           
       }
       if (this.x == null) {
           this.x = 0;
       }
       if (this.y == null) {
           this.y = 0;
       }
        Map<String, Object> action = moveAction(this.x.intValue() + x.intValue(), this.y.intValue() + y.intValue());
        actions.add(action);
        return this;
    }    

    @Override
    public DriverMouse down() {
        Map<String, Object> map = new HashMap();
        map.put("type", "pointerDown");
        map.put("button", 0);
        actions.add(map);
        return this;
    }

    @Override
    public DriverMouse up() {
        Map<String, Object> up = new HashMap();
        up.put("type", "pointerUp");
        up.put("button", 0);
        actions.add(up);
        return go();
    }

    @Override
    public DriverMouse submit() {
        driver.submit();
        return this;
    }

    @Override
    public DriverMouse click() {
        return down().up();
    }

    @Override
    public DriverMouse doubleClick() {
        String js = "document.elementFromPoint(" + x + "," + y + ").dispatchEvent(new MouseEvent('dblclick'))";
        driver.script(js);
        return this;
    }

    @Override
    public DriverMouse go() {
        Map<String, Object> map = new HashMap();
        map.put("type", "pointer");
        map.put("id", "1");
        map.put("actions", actions);
        driver.actions(Collections.singletonList(map));
        actions.clear();
        return this;
    }

}

public DriverMouse(Driver driver) {
        this.driver = driver;
    }

